// Declarations transcribed from solid-js@2.0.0-rc.17 and @solidjs/signals@2.0.0-rc.17. Byte-faithful where a claim reads them: `runWithOwner`
// (`dist/types/core/core.d.ts:340`) and `getOwner` (`dist/types/core/owner.d.ts:66`), up to the `export declare` -> `export` an ambient block forbids.
// Reduced, with no claim reading them back: `Owner` to the interface's name, `createSignal` to its value overload, `createEffect` to its two-function
// shape (`dist/types/signals.d.ts:427`) whose apply returns `(() => void) | void`, as the package says, `createReaction` (`:531`) to the form this fixture
// calls, and `Errored`/`Loading` (`types/client/flow.d.ts:205`, `:273`) to the props they pass.
export interface Owner {}
export type Accessor<T> = () => T;
export type Setter<T> = (value: T) => T;
export declare function createSignal<T>(value: T): [get: Accessor<T>, set: Setter<T>];
export declare function createEffect<Next, Init = Next>(
  compute: (prev: Init | Next) => Next,
  effect: (value: Next, prev?: Next) => (() => void) | void,
  options?: object
): void;
export declare function createReaction(effect: () => void | (() => void)): (tracking: () => void) => void;
export declare function getOwner(): Owner | null;
export declare function runWithOwner<T>(owner: Owner | null, fn: () => T): T;
export declare function createTrackedEffect(compute: () => void | (() => void), options?: object): void;
export declare function onSettled(callback: () => void | (() => void)): void;
export declare function resolve<T>(fn: () => T): Promise<T>;
export declare function until<T>(fn: () => T, options?: object): Promise<T>;
